contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 seed1, uint256 seed2) public {
        vm.assume(caller != address(0));
        // Seed random outcomes by varying block timestamp/difficulty via vm.warp/vm.roll
        vm.warp(seed1);
        vm.roll(seed2);
        vm.deal(caller, 20 ether);
        vm.startPrank(caller);
        c.play{value: 10}();
        uint256 potAfterFirst = c.pot();
        vm.warp(seed1 + 1);
        vm.roll(seed2 + 1);
        c.play{value: 10}();
        uint256 potAfterSecond = c.pot();
        vm.stopPrank();
        // General property: if pot after first call is non-zero, then after two calls pot can be non-zero as well
        // (because second call might not win). The buggy version always resets pot to 0, so after two calls pot is always 0.
        assertTrue(potAfterFirst == 0 || potAfterSecond == 10 || potAfterSecond == 0);
    }
}

