pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 plays, uint8[2] memory timestamps, uint256[2] memory difficulties) public {
        // Bound plays to a reasonable number of iterations
        plays = bound(plays, 1, 20);
        // Ensure timestamps are strictly increasing (block.timestamp must advance)
        vm.assume(timestamps[0] < timestamps[1]);
        // Set initial timestamp
        vm.warp(timestamps[0]);
        vm.roll(1);
        vm.difficulty(difficulties[0]);

        for (uint256 i = 0; i < plays; i++) {
            uint8 ts = timestamps[i % 2];
            uint256 diff = difficulties[i % 2];
            // Advance time to avoid same timestamp re-use
            vm.warp(ts + i);
            vm.roll(1 + i);
            vm.difficulty(diff + i);

            address player = address(uint160(uint256(keccak256(abi.encodePacked(i)))));
            vm.deal(player, 10 ether);
            vm.prank(player);
            c.play{value: 10}();
        }

        // Property: pot never exceeds initial ticket amount
        assertTrue(c.pot() <= 10);
    }
}

