pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint8 n) public {
        vm.assume(n >= 2 && n <= 10);
        Reverter reverter = new Reverter();
        address bankAddr = reverter.payableAddr();
        // set c.bank to the reverter
        vm.store(address(c), bytes32(uint(0)), bytes32(uint(uint160(bankAddr))));
        uint256 totalSent = 0;
        for (uint256 i = 0; i < n; i++) {
            uint256 senderKey = uint256(keccak256(abi.encodePacked(i, "player")));
            address player = vm.addr(senderKey);
            vm.deal(player, 10 ether);
            vm.prank(player);
            c.play{value: 10}();
            totalSent += 10;
        }
        assertTrue(c.pot() < totalSent);
    }
}

contract Reverter {
    fallback() external payable { revert(); }
    function payableAddr() external view returns (address) {
        return address(this);
    }
}

