pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 plays, uint8[3] memory seeds) public {
        vm.assume(plays > 0 && plays <= 10);
        uint256 totalPaidIn = 0;
        uint256 totalPaidOut = 0;
        for (uint256 i = 0; i < plays; i++) {
            address player = address(uint160(uint256(keccak256(abi.encode(seeds[0], seeds[1], seeds[2], i)))));
            vm.deal(player, 10 ether);
            vm.prank(player);
            try c.play{value: 10}() {
                if (uint256(keccak256(abi.encode(block.timestamp, block.difficulty, i))) % 2 == 0) {
                    totalPaidOut += 10;
                }
            } catch {
                continue;
            }
            totalPaidIn += 10;
        }
        assertTrue(c.pot() == totalPaidIn - totalPaidOut);
    }
}
